// 그리드 조회된 결과없습니다. 메세지 show/hide 용 위한 변수

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        MaxTab_01.setSelectedTabIndex("1");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70030.onpageload" });
    }
};

/**
 * @method
