 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", procJob));
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70030.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", procJob));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70030.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        // 신규 팝업 버튼 클릭
        if (txb_SearchIsuCd1.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            return;
        }
        if (MaxTab_01.getSelectedTabIndex() === "1") {
            // 종목명 변경 또는 증권의 분할/병합
            await scwin.popIsuNmChg("N", -1, ""); //-1은 의미 없음

        } else if (MaxTab_01.getSelectedTabIndex() === "2") {
            // 기타감소
            await scwin.popQtyIsur("N", -1, ""); //-1은 의미 없음

        } else if (MaxTab_01.getSelectedTabIndex() === "3") {
            // 만기변경
            await scwin.popExpIsur("N", -1, ""); //-1은 의미 없음

        } else {
            // 기타변경
            await scwin.popEtcIsur("N", -1, ""); //-1은 의미 없음

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70030.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        // 닫기
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70030.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        // 엑셀저장
        const isExcelDown = false;
        let xls_path;
        let countIsur = 0;
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        if (MaxTab_01.getSelectedTabIndex() === "1") {
            countIsur = dts_nm_change.getRowCount();
            if (countIsur > 0) {
                $c.data.downloadGridViewExcel(grd_Itm_List1, {fileName: "종목명/증권분할·병합 내역", type: 8});
            } else {
                await $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
            }
        } else if (MaxTab_01.getSelectedTabIndex() === "2") {
            countIsur = dts_qty_change.getRowCount();
            if (countIsur > 0) {
                $c.data.downloadGridViewExcel(grd_Itm_List2, {fileName: "기타수량감소 내역", type: 8});
            } else {
                await $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
            }
        } else if (MaxTab_01.getSelectedTabIndex() === "3") {
            countIsur = dts_exp_change.getRowCount();
            if (countIsur > 0) {
                $c.data.downloadGridViewExcel(grd_Itm_List3, {fileName: "만기변경 내역", type: 8});
            } else {
                await $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
            }
        } else {
            countIsur = dts_etc_change.getRowCount();
            if (countIsur > 0) {
                $c.data.downloadGridViewExcel(grd_Itm_List4, {fileName: "기타변경 내역", type: 8});
            } else {
                await $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70030.btn_Excel_onclick" });
    }
};

