scwin.btn_Search1_onclick = async function() {
    try {
        // 상장신청인
        if ($c.ut.trim(txb_ISUR_CD1.getValue()) === "") {
            txb_ISUR_CD1.setValue("");
            txb_ISUR_NM1.setValue("");
        }
        // 종목
        if ($c.ut.trim(txb_SearchIsuCd1.getValue()) === "") {
            txb_SearchIsuCd1.setValue("");
            txb_SearchIsuNm1.setValue("");
        }

        // 조회
        await scwin.readSync("Y");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70030.btn_Search1_onclick" });
    }
};

