///////// 4. 서브미션 콜백 영역 /////////
// 팝업 구분 (신규:N, 수정:U) > 팝업 전달인자

/**
 * @method
 * @name listNmChglistSync
 * @description 종목명변경의 종목명 변경상장 내역 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listNmChglistSync = async function() {
    // 발행 및 상장 내역 조회
    url += "&SCREN_ID=" + "ULDSTF70030.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + txb_ISUR_CD1.getValue(); // 상장신청인
    url += "&SRCH_ISU_CD=" + txb_SearchIsuCd1.getValue(); // 종목코드

    const sbmOptions = {
        id : "sbm_dts_nm_change",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_nm_change=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // '조회된결과없습니다' 메세지숨김
    if (scwin.vTotalCountGrid1 > 0) {
        $c.lcd.fn_CloseNoData();
    } else {
    }
};

/**
 * @method
 * @name listQtyChglistSync
 * @description 기타수량감소 내역 조회
 * @returns {Promise<void>}
 * @hidden N
