/**
 * @method
 * @name getParIsur
 * @description 상장신청인 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD1.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISUR_NM1.getValue(); // 명칭값을 포함할 컨트롤
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD1.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM1.setValue(arrPar[0].ISUR_NM);
    }
};

/**
 * @method
 * @name getParIsur2
 * @description 종목명 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = txb_SearchIsuCd1.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_SearchIsuNm1.getValue(); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur2
 * @description set Par Isur2 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur2 = async function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    await scwin.setCodeIsur(arrPar[0].ISUR_CD); // 상장신청인 정보 불러오기

    if (dbClickYn === "Y") {
        txb_SearchIsuCd1.setValue(arrPar[0].ISU_CD);
        txb_SearchIsuNm1.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};

/**
 * @method
 * @name popIsuNmChg
 * @description 종목명변경  > 종목명변경 상장내역 > 팝업
 * @param {*} kind kind
 * @param {*} rowno rowno
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popIsuNmChg = async function(kind, rowno, colid) {
    vPTitle = "종목명변경/증권분할·병합 ";
    scwin.vIsuChgKind = kind; // 팝업전달인자(N:신규, U:수정)

    if (kind === "N") {
        // row data of grid
        scwin.clickBzProcsNo = "";
        scwin.clickIsuCd = txb_SearchIsuCd1.getValue();
        vPTitle = vPTitle + "신규";
    } else if (kind === "U") {
        // data of textcontrol
        scwin.clickBzProcsNo = dts_nm_change.getCellData(rowno, "BZ_PROCS_NO"); // 업무처리코드
        scwin.clickIsuCd = dts_nm_change.getCellData(rowno, "ISU_CD"); // 종목명코드
        scwin.clickDisclsYn = dts_nm_change.getCellData(rowno, "DISCLS_YN"); // 공시여부

        vPTitle = vPTitle + "세부내역";
    }
    const options = {
        id: "" + scwin.pNmChgID + "",
        title: vPTitle,
        type: "browserPopup",
        width: "850px",
        height: "510px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../digital/" + scwin.pNmChgID + ".gfm", options);
};

