/**
 * @method
 * @name readSync
 * @description 변경상장 > 조회
 * @param {*} msgKind msgKind
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function(msgKind) {
    // 필수값 체크
    // 상장인 명 또는 종목  선택 조회가능
    if ($c.ut.trim(txb_ISUR_CD1.getValue()) === "" & $c.ut.trim(txb_SearchIsuCd1.getValue()) === "") {
        if (msgKind === 'Y') {
            await $c.win.alert("상장신청인 또는 종목을 선택해주세요.");
        }
        return;
    }
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dts_nm_change.removeAll();
        // 종목명 변경 조회
        await scwin.listNmChglistSync();
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dts_qty_change.removeAll();
        // 기타수량감소 조회
        await scwin.listQtyChglistSync();
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        dts_exp_change.removeAll();
        // 만기변경 조회
        await scwin.listExpChglistSync();
    } else {
        dts_etc_change.removeAll();
        // 기타 변경 조회
        await scwin.listEtcChglistSync();
    }
};
